traps.Trap02.txt:
	If ($Event <> 234) @end;
	StopMusic();		
	PlayerGoto(12, 27);
	SetPlayerDir(4);
	Watch("杨影枫", "卓非凡", 0);

	Say("杨影枫：大哥！你回来了！", 2);
	Say("卓非凡：哦，是贤弟你呀，大哥近日俗事纷杂，分身乏术，这些日不曾去芭蕉小筑看你，你过的可好？", 33);
	Say("杨影枫：还好，多谢大哥关心！…… 大哥，我有一事相告，还望大哥赎罪。", 2);
	Say("卓非凡：贤弟怎么如此客气，不知何事，但说无妨！", 33);
	Say("杨影枫：说来话长，我在芭蕉小筑的这几日发生了一些事。", 2);
	Say("卓非凡：哦？是何事？", 33);
	Say("杨影枫：长话短说，我在一群恶人的手里救了一位女子，结果仇家报仇烧毁了芭蕉小筑，还将那位姑娘打伤。", 2);
	Say("卓非凡：啊？！竟会发生这种事，真是岂有此理！贤弟，你知不知道哪帮恶贼是什么人，我一定为你报仇！", 33);
	Say("杨影枫：多谢大哥，不用大哥费心了，那帮恶贼只不过是一群江湖混混，已经被我铲除了。只是连累大哥的芭蕉小筑被烧毁，真是十分对不住！", 2);
	Say("卓非凡：贤弟不必放在心上，一间房子而已，没有什么大不了，烧了还可以重建嘛。", 33);
	Say("杨影枫：多谢大哥！我还有一事想问大哥，不知大哥最近可有打听到张仲天的死因？", 2);
	Say("卓非凡：不瞒贤弟，最近我一直在打听消息，只可惜没有什么结果。", 33);
	Say("杨影枫：（奇怪，惠安镇上已经传的沸沸扬扬，连小叁子都听说了，大哥怎会不知？莫非……）是吗？", 2);
	Say("卓非凡：贤弟，难道你听说了什么消息？", 33);
	Say("杨影枫：哦，也没什么，道听途说罢啦。", 2);
	Say("卓非凡：（难道他知道了什么？）贤弟，说来听听，也许可以查出点线索。", 33);
	Say("杨影枫：我听说是为了争夺一部什么经书，也不知是真是假，不过……我听说此事好像与大哥有关。", 2);

//	Talk(3390, 3450);
	NpcGoto("卓非凡", 12, 19);
	SetNpcDir("卓非凡",4);
	Say("卓非凡：（难道这小子已经知道了？！）", 35);
	NpcGoto("卓非凡", 13, 11);
	SetNpcDir("卓非凡",5);
	MoveScreen(4, 100, 2);
	Say("卓非凡：贤弟，江湖中人如何诬陷我都无所谓，想不到连你也不信任我！想我卓非凡堂堂正正大丈夫，怎会去做那杀人灭口之事？！", 34);
//	Talk(3460, 3460);
	PlayerRunTo(14, 10);
	SetPlayerDir(1);
	Say("杨影枫：那些人并没有说大哥干了什么坏事啊，大哥怎么会想到杀人灭口？莫非……", 4);
//	Talk(3470, 3480);
	Sleep(200);
	Say("卓非凡：啊！这个…… 去死吧你！", 35);
//	Talk(3481, 3481);
	NpcSpecialAction("卓非凡", "npc009_at.asf");
